module.header:
extern const flash_instance_t ${module.driver.mram.name};
extern mram_instance_ctrl_t ${module.driver.mram.name}_ctrl;
extern const flash_cfg_t ${module.driver.mram.name}_cfg;
#ifndef ${module.driver.mram.enter}
fsp_err_t ${module.driver.mram.enter}(void const * p_context);
#endif
#ifndef ${module.driver.mram.exit}
void ${module.driver.mram.exit}(void const * p_context, bool hardware_idle);
#endif
#ifndef ${module.driver.mram.time}
uint32_t ${module.driver.mram.time}(void const * p_context);
#endif

module.declarations:
mram_instance_ctrl_t ${module.driver.mram.name}_ctrl;
const mram_extended_cfg_t ${module.driver.mram.name}_extend =
{
    .code_start = ${module.driver.mram.alias},
    .mriclk_hz = ${module.driver.mram.mriclk_hz},
    .mrpclk_hz = ${module.driver.mram.mrpclk_hz},
    .timeout_us = ${module.driver.mram.timeout_us},
    .p_enter = ${module.driver.mram.enter},
    .p_exit = ${module.driver.mram.exit},
    .p_time_us = ${module.driver.mram.time},
    .p_context = ${module.driver.mram.context},
};
const flash_cfg_t ${module.driver.mram.name}_cfg =
{
    .data_flash_bgo = false,
    .p_callback = NULL,
    .p_context = NULL,
    .p_extend = &${module.driver.mram.name}_extend,
    .ipl = BSP_IRQ_DISABLED,
    .irq = FSP_INVALID_VECTOR,
    .err_ipl = BSP_IRQ_DISABLED,
    .err_irq = FSP_INVALID_VECTOR,
};
const flash_instance_t ${module.driver.mram.name} =
{
    .p_ctrl = &${module.driver.mram.name}_ctrl,
    .p_cfg = &${module.driver.mram.name}_cfg,
    .p_api = &g_flash_on_mram,
};
